export function tr(s) {
  if (LANG === 'ro' || typeof s !== 'string' || !s.trim()) return s
  const hit = EN[s]
  if (hit != null) return hit
  if (s.endsWith(' *') && EN[s.slice(0, -2)]) return `${EN[s.slice(0, -2)]} *`
  for (const [re, rep] of PATTERNS) if (re.test(s)) return s.replace(re, rep)
  return s
}
